"„Die Mauer hält die Monster draußen. Solange du drinnen bist, bist du sicher.“": "«Le mura tengono fuori i mostri. Finché sei dentro, sei al sicuro.»",
"„Die Wildschweine fressen mir die Rüben weg. Wenn du welche siehst, jag sie!“": "«I cinghiali mi mangiano le rape. Se ne vedi qualcuno, cacciali!»",
"„Hast du schon mal einen Drachen gesehen? Lian sagt, am Feuerberg gibt es welche.“": "«Hai mai visto un drago? Lian dice che sul Monte di Fuoco ce ne sono.»",
"„Früher war Kazehana eine ruhige Stadt. Dann kamen die Steine.“": "«Un tempo Kazehana era una città tranquilla. Poi arrivarono le pietre.»",
"„Jeder Stein hat seine eigene Seele. Und jeder lässt etwas anderes zurück.“": "«Ogni pietra ha la sua anima. E ognuna lascia qualcosa di diverso.»",
