"Stadt · sicherer Ort": "Città · luogo sicuro",
"Lager · sicherer Ort": "Campo · luogo sicuro",
"Die große Stadt Kazehana mit den grünen Sonnenwiesen.": "La grande città di Kazehana con i verdi Prati del Sole.",
"Dichter Nadelwald mit Banditen, Spinnen und Bären. Spinnenhöhle und Banditenkeller.": "Fitta foresta di conifere con banditi, ragni e orsi. Grotta dei Ragni e Cantina dei Banditi.",
"Staubiges Tal der Orks und Skorpione. Orkfestung.": "Polverosa valle di orchi e scorpioni. Fortezza degli Orchi.",
"Graue Aschenebene mit Ogern und Dämonen. Totengruft.": "Grigia piana di cenere con ogre e demoni. Cripta dei Morti.",
"Eisige Gipfel mit Eiswölfen, Yetis und Frostgeistern. Eisgrotte.": "Vette ghiacciate con lupi dei ghiacci, yeti e spiriti del gelo. Grotta di Ghiaccio.",
"Nebliges Moor voller Untoter, Hexen und Ghule.": "Palude nebbiosa piena di non morti, streghe e ghoul.",
"Schwarzer Basalt und Lavaflüsse, Golems, Feuerdämonen und Drachen. Drachenhort.": "Basalto nero e fiumi di lava, golem, demoni del fuoco e draghi. Covo del Drago.",
"Du wirbelst um dich selbst, triffst alle Gegner im Umkreis und betäubst sie kurz.": "Ruoti su te stesso, colpisci tutti i nemici intorno e li stordisci brevemente.",
"Buff: Blitze zucken um dich. Mehr Angriffstempo und Lauftempo.": "Buff: fulmini guizzano intorno a te. Più velocità d'attacco e di movimento.",
"Erdbeben": "Terremoto",
"Du stampfst auf und der Boden bebt: Alle Gegner um dich werden {0} s betäubt.": "Pesti il suolo e la terra trema: tutti i nemici intorno sono storditi per {0} s.",
"Starker Körper": "Corpo forte",
"Buff: Dein Körper wird hart wie Stein. Mehr Verteidigung und weniger erlittener Schaden.": "Buff: il tuo corpo diventa duro come la pietra. Più difesa e meno danni subiti.",
"Geistesschlag": "Colpo dello spirito",
"Ein gebündelter Schlag mit voller Kraft auf ein einzelnes Ziel. Sehr hoher Schaden.": "Un colpo concentrato con tutta la forza su un solo bersaglio. Danno altissimo.",
"Kriegsschrei": "Grido di guerra",
"Ein Schrei, der Gegner lähmt: Sie werden langsamer und nehmen mehr Schaden.": "Un grido che paralizza i nemici: diventano più lenti e subiscono più danni.",
"Du drehst dich mit beiden Dolchen und triffst alle Gegner um dich.": "Ruoti con entrambi i pugnali e colpisci tutti i nemici intorno.",
"Schattensprung": "Salto d'ombra",
"Du springst durch die Schatten nach vorn und schneidest alles auf dem Weg.": "Salti in avanti attraverso le ombre e tagli tutto sul tuo cammino.",
"Lähmende Klinge": "Lama paralizzante",
"Ein Stich in die Sehnen: Das Ziel ist {0} s betäubt und {1} s vergiftet.": "Un colpo ai tendini: il bersaglio è stordito per {0} s e avvelenato per {1} s.",
"Schattenmantel": "Manto d'ombra",
"Buff: Schatten hüllen dich ein. Mehr Ausweichen und mehr kritische Treffer.": "Buff: le ombre ti avvolgono. Più schivata e più colpi critici.",
"Buff: Drachenkraft fließt in dich. Mehr Angriff und mehr Fertigkeitsschaden.": "Buff: la forza del drago scorre in te. Più attacco e più danno abilità.",
"Geisterfaust": "Pugno spirituale",
"Eine Faust aus Geisterkraft trifft ein Ziel und betäubt es {0} s.": "Un pugno di forza spirituale colpisce un bersaglio e lo stordisce per {0} s.",
"Windfessel": "Vincolo del vento",
"Wirbelnder Wind fesselt Gegner um dich: Sie werden langsamer und verwundbar.": "Un vento vorticoso immobilizza i nemici intorno: diventano più lenti e vulnerabili.",
"Segen": "Benedizione",
"Buff: Weniger erlittener Schaden, Leben regeneriert sich, mehr kritische Treffer.": "Buff: meno danni subiti, la vita si rigenera, più colpi critici.",
"Heilung": "Cura",
"Heilt einen Teil deines Lebens und gibt dir danach mehr Angriff.": "Cura parte della tua vita e poi ti dà più attacco.",
