"Der erste Seelenstein": "La prima pietra dell'anima",
"Wolfsplage": "Piaga dei lupi",
"Die Wölfe werden mutiger. Dünne das Rudel aus, ehe sie das Tor erreichen.": "I lupi diventano più audaci. Sfoltisci il branco prima che raggiungano la porta.",
"Verirrte Hirsche": "Cervi smarriti",
"Der Alpha": "L'alfa",
"Hinter den Wölfen stehen ihre Anführer, die Alpha-Wölfe. Ohne sie zerfällt das Rudel.": "Dietro i lupi ci sono i loro capi, i lupi alfa. Senza di loro il branco si sfalda.",
"Keiler in den Rüben": "Cinghiali tra le rape",
"Stein der Wut": "Pietra dell'Ira",
"Auf in den Dunkelwald": "Verso il Bosco Oscuro",
"Banditen im Dunkelwald": "Banditi nel Bosco Oscuro",
"Kapitel {0} · Dunkelwald": "Capitolo {0} · Bosco Oscuro",
"Schützen im Dickicht": "Arcieri nella boscaglia",
"Aus den Baumkronen schießen Banditen auf alles, was sich bewegt. Hol sie herunter.": "Dalle chiome degli alberi i banditi tirano su tutto ciò che si muove. Buttali giù.",
"Netz der Spinnen": "La rete dei ragni",
"Stein der Gier": "Pietra dell'Avidità",
"Zwei Steine der Gier locken Banditen an wie Gold die Diebe. Zerschlage sie.": "Due Pietre dell'Avidità attirano i banditi come l'oro i ladri. Distruggile.",
"Lautlose Jäger": "Cacciatori silenziosi",
"Luchse reißen unsere Späher, ohne dass einer sie kommen sieht. Sei wachsamer als sie.": "Le linci sbranano i nostri esploratori senza che nessuno le veda arrivare. Sii più vigile di loro.",
"Der Banditenfürst": "Il signore dei banditi",
"Der Braunbär": "L'orso bruno",
"Ein Rudel Braunbären hat den Holzfällerpfad besetzt. Sie sind stark, sei vorsichtig.": "Un branco di orsi bruni ha occupato il sentiero dei taglialegna. Sono forti, fai attenzione.",
