"Hyänen der Orks": "Le iene degli orchi",
"Die Schamanen": "Gli sciamani",
"Ihre Schamanen rufen Flüche über das Tal. Ohne sie verlieren die Orks ihren Mut.": "I loro sciamani lanciano maledizioni sulla valle. Senza di loro gli orchi perdono coraggio.",
"Stein der Schwärze": "Pietra dell'Oscurità",
"Die Orks beten schwarze Steine an. Nimm ihnen ihre Götzen.": "Gli orchi adorano pietre nere. Porta via i loro idoli.",
"Stachel im Sand": "Pungiglione nella sabbia",
"In den Felsspalten nisten Riesenskorpione. Ihr Gift lähmt einen Ochsen. Räum die Spalten.": "Nelle fenditure delle rocce nidificano scorpioni giganti. Il loro veleno paralizza un bue. Ripulisci le fenditure.",
"Der Ork-Hauptmann": "Il capitano orco",
"Ohne ihre Hauptmänner sind die Orks nur ein wilder Haufen. Finde sie.": "Senza i loro capitani gli orchi sono solo un'orda selvaggia. Trovali.",
"Stein der Asche": "Pietra della Cenere",
"Der Stein der Asche verbrennt das Tal von innen. Lösch ihn aus, bevor nur Staub bleibt.": "La Pietra della Cenere brucia la valle dall'interno. Spegnila prima che resti solo polvere.",
"Asche über dem Ödland": "Cenere sulle Terre Desolate",
"Oger im Aschenfeld": "Ogre nel campo di cenere",
"Thrak hatte recht, dich zu schicken. Oger plündern unser Lager jede Nacht. Halte sie fern.": "Thrak ha fatto bene a mandarti. Gli ogre saccheggiano il nostro campo ogni notte. Tienili lontani.",
"Kapitel {0} · Ödland": "Capitolo {0} · Terre Desolate",
"Wargrudel": "Branco di warg",
"Wargs folgen den Ogern und fressen, was diese übrig lassen. Jag das Rudel.": "I warg seguono gli ogre e mangiano ciò che lasciano. Caccia il branco.",
"Dämonen im Ödland": "Demoni nelle Terre Desolate",
"Aus den Rissen im Ödland steigen Dämonen. Treib sie zurück in die Tiefe.": "Dalle crepe delle Terre Desolate salgono demoni. Ricacciali nell'abisso.",
"Stein der Glut": "Pietra della Brace",
"Die Steine der Glut lassen das Ödland brennen. Lösche sie aus.": "Le Pietre della Brace fanno bruciare le Terre Desolate. Spegnile.",
"Höllenhunde": "Segugi infernali",
"Dreiköpfige Hunde bewachen die Risse. Wer sie besiegt, kann den Rissen nahe kommen.": "Cani a tre teste sorvegliano le crepe. Chi li sconfigge può avvicinarsi alle crepe.",
"Die Oase im Süden": "L'oasi a sud",
"Kobras in der Wüste": "Cobra nel deserto",
"Kapitel {0} · Schlangental": "Capitolo {0} · Valle dei Serpenti",
"Das Rasseln im Sand": "Il sonaglio nella sabbia",
"Stein der Schatten": "Pietra delle Ombre",
"Im Dschungel würgen Pythons ganze Ochsen. Wer dort Holz schlägt, kommt nicht wieder.": "Nella giungla i pitoni stritolano buoi interi. Chi va a tagliare legna non torna più.",
"Schwarze Panther": "Pantere nere",
"Die Panther der Nagas jagen in der Nacht. Mach den Dschungel wieder sicher.": "Le pantere dei naga cacciano di notte. Rendi di nuovo sicura la giungla.",
"Eis im Norden": "Ghiaccio a nord",
"Eiswölfe": "Lupi dei ghiacci",
"Hakim hat dich geschickt? Gut. Eiswölfe umkreisen unser Lager, sie riechen jede Schwäche.": "Ti manda Hakim? Bene. I lupi dei ghiacci girano attorno al nostro campo, fiutano ogni debolezza.",
"Kapitel {0} · Frostgipfel": "Capitolo {0} · Vetta Gelata",
"Der Yeti": "Lo yeti",
"Stein des Frostes": "Pietra del Gelo",
"Zwei Steine des Frostes lassen den Gipfel nie mehr tauen. Zerschlage sie.": "Due Pietre del Gelo impediscono alla vetta di sgelare. Distruggile.",
"Wilde Mammuts": "Mammut selvaggi",
"Frostgeister": "Spiriti del gelo",
"In den Schneestürmen wandern Geister. Wer sie berührt, erfriert von innen.": "Nelle tormente vagano spiriti. Chi li tocca congela dall'interno.",
"Stein der Stille": "Pietra del Silenzio",
"Der Eiskönig": "Il re dei ghiacci",
"Alles Eis gehorcht dem Eiskönig in der Eisgrotte. Bezwinge ihn, dann taut der Gipfel.": "Tutto il ghiaccio obbedisce al re dei ghiacci nella Grotta di Ghiaccio. Sconfiggilo e la vetta si scioglierà.",
"Nebel über dem Moor": "Nebbia sulla palude",
"Das Totenmoor": "La Palude dei Morti",
"Kapitel {0} · Totenmoor": "Capitolo {0} · Palude dei Morti",
"Moorwölfe": "Lupi di palude",
"Die Wölfe hier sind halb tot und hören nicht auf zu jagen. Gib ihnen den Rest.": "Qui i lupi sono mezzi morti e non smettono di cacciare. Finiscili.",
"Die Sumpfhexen": "Le streghe della palude",
"Hexen beschwören die Toten aus dem Schlamm. Ohne sie bleiben die Gräber zu.": "Le streghe evocano i morti dal fango. Senza di loro le tombe restano chiuse.",
"Stein der Fäulnis": "Pietra della Putrefazione",
"Zwei Steine der Fäulnis vergiften das Wasser. Nichts Lebendes wächst mehr.": "Due Pietre della Putrefazione avvelenano l'acqua. Non cresce più nulla di vivo.",
"Ghule": "Ghoul",
"Die Ghule fressen, was die Hexen erwecken. Sie sind schnell und hungrig. Sei schneller.": "I ghoul divorano ciò che le streghe risvegliano. Sono veloci e affamati. Sii più veloce.",
"Donner in der Klamm": "Tuono nella gola",
"Oswin hat dich geschickt? Die Trolle belagern die Klamm. Zeig ihnen unsere Stärke.": "Ti manda Oswin? I troll assediano la gola. Mostra loro la nostra forza.",
"Kapitel {0} · Donnerklamm": "Capitolo {0} · Gola del Tuono",
"Harpyien": "Arpie",
"Harpyien stoßen auf jeden herab, der den Pass hinaufsteigt. Hol sie aus der Luft.": "Le arpie piombano su chiunque risalga il passo. Abbattile.",
"Die Minotauren": "I minotauri",
"Minotauren rennen mit gesenkten Hörnern gegen unsere Tore. Halte sie auf.": "I minotauri caricano le nostre porte a corna basse. Fermali.",
"Stein der Pein": "Pietra del Tormento",
"Blutrote Steine wachsen aus den Felsen. Sie nähren sich von Schmerz.": "Pietre rosso sangue crescono dalle rocce. Si nutrono di dolore.",
"Erwachte Titanen": "Titani risvegliati",
"Auf dem Titanenkamm stehen die Steintitanen auf. Bring sie wieder zum Stehen – für immer.": "Sulla Cresta dei Titani si alzano i titani di pietra. Fermali di nuovo – per sempre.",
"Der Berg brennt": "La montagna brucia",
"Lavagolems": "Golem di lava",
"Gunhild schickt dich? Dann bist du bereit. Golems aus Lava wälzen sich auf unser Lager zu.": "Ti manda Gunhild? Allora sei pronto. Golem di lava avanzano verso il nostro campo.",
"Kapitel {0} · Feuerberg": "Capitolo {0} · Monte di Fuoco",
"Glutkatzen": "Gatti di brace",
"Glutkatzen streifen durch die Lavafelder. Wo sie laufen, brennt der Boden.": "I gatti di brace si aggirano tra i campi di lava. Dove passano, il suolo brucia.",
"Stein der Flamme": "Pietra della Fiamma",
"Zwei Steine der Flamme heizen den Berg an. Ohne sie verlöschen die Lavaflüsse.": "Due Pietre della Fiamma scaldano la montagna. Senza di loro i fiumi di lava si spengono.",
"Feuerdämonen": "Demoni del fuoco",
"Aus den Kratern steigen Feuerdämonen. Treib sie zurück ins Feuer.": "Dai crateri salgono demoni del fuoco. Ricacciali nelle fiamme.",
"Feuerdrachen": "Draghi di fuoco",
"Am Feuerberg nisten Drachen. Wenn sie flügge werden, ist kein Dorf mehr sicher.": "Sul Monte di Fuoco nidificano draghi. Quando spiccheranno il volo, nessun villaggio sarà al sicuro.",
"Stein des Untergangs": "Pietra della Rovina",
"Heimkehr nach Kazehana": "Ritorno a Kazehana",
