"Kaum sind die Hunde fort, schleichen die Füchse um die Ställe. Jag sie zurück in die Wiesen": "Appena spariti i cani, le volpi girano intorno alle stalle. Ricacciale nei prati",
"Die Wildschweine fressen den Bauern die Ernte weg. Ein Winter ohne Vorräte wäre unser Ende": "I cinghiali divorano il raccolto dei contadini. Un inverno senza scorte sarebbe la nostra fine",
"Am Rand der Wiesen glüht ein Stein der Wut. Seine Wut macht die Tiere rasend – zerschlag ihn": "Al margine dei prati brilla una pietra dell'ira. La sua furia fa impazzire gli animali – spezzala",
"Gut, dass Bao dich schickt. Banditen überfallen jeden Händler auf dem Waldweg. Vertreib sie": "Meno male che Bao ti manda. I banditi assaltano ogni mercante sulla strada del bosco. Scacciali",
"Die Keiler hier haben Dornen statt Borsten. Sie zerreißen unsere Fallen – und die Fallensteller": "I cinghiali qui hanno spine al posto delle setole. Fanno a pezzi le trappole – e i cacciatori",
"Tief im Wald spinnen riesige Spinnen ihre Netze über die Wege. Brenne sie aus, wenn es sein muss": "Nel cuore del bosco ragni giganti tessono ragnatele sui sentieri. Bruciale se serve",
"Mitten im Wald wächst ein Stein der Dornen. Seine Ranken ersticken jeden Baum. Zerstöre ihn": "In mezzo al bosco cresce una pietra di spine. I suoi rovi soffocano ogni albero. Distruggila",
"Hagen schickt dich? Dann komm, die Orks stehen schon vor unseren Palisaden. Schwäche ihr Heer": "Ti manda Hagen? Allora vieni, gli orchi sono già davanti alle palizzate. Indebolisci il loro esercito",
"Die Orks halten Hyänen wie Hunde und hetzen sie auf unsere Kundschafter. Erledige die Meute": "Gli orchi tengono iene come cani e le aizzano contro i nostri esploratori. Elimina il branco",
"Idris schickt dich? Die Götter meinen es gut mit Sahra. Die Kobras lauern an jeder Wasserstelle": "Ti manda Idris? Gli dei sono benevoli con Sahra. I cobra in agguato a ogni pozza",
"Hörst du das Rasseln? Klapperschlangen. Hunderte. Die Karawanen trauen sich nicht mehr los": "Senti quel sonaglio? Serpenti a sonagli. Centinaia. Le carovane non osano più partire",
"Auf dem Frostgipfel sind Yetis gesehen worden, so groß wie Häuser. Bring ihre Felle als Beweis": "Sul Picco del Gelo sono stati visti yeti grandi come case. Porta le loro pelli come prova",
"Die Mammuts sind rasend, seit der Frost nicht weicht. Sie zertrampeln unsere Vorratshütten": "I mammut sono furiosi da quando il gelo non cede. Calpestano le nostre capanne delle provviste",
"Wo der Stein der Stille steht, verstummt jedes Lied. Bring den Klang zurück auf den Gipfel": "Dove sorge la pietra del silenzio, ogni canto tace. Riporta il suono sulla vetta",
"Der letzte und mächtigste aller Seelensteine. Zerstöre ihn, und die Steine hören auf zu wachsen": "L'ultima e più potente di tutte le pietre dell'anima. Distruggila e le pietre smetteranno di crescere",
